// 多语言补充字典（第十五轮）。
//
// 为什么单独一个文件：`i18n.dart` 里的 `dict` 只有 zh(原文)/en(完整)/ja(缺 55 键)/
// fr·ru·es·ar(各只有 8 个词)。界面文案用中文原文当 key，字典缺词就**回落中文** ——
// 于是切到法语/俄语/西语/阿语，除了模块名，屏幕上剩下的全是中文。这属于「假完成」：
// 语言列表宣称 7 种，实际可用的只有 zh/en/ja。
//
// ★2026-09-28 更正上一句：`dict` 里**并没有 zh 块** —— "zh(原文)" 是**描述口径**，
//   不是一条真实存在的字典项（中文原文本身就是 key，不需要翻译表）。
//   当时把这句话当成事实，推导出「缺词会回落中文」，进而给 `tr()` 加了「英文」中间跳，
//   结果 `dict['zh']` 为 null → 中文用户直接掉进英文兜底，全屏英文。
//   事实是：**中文的地位只能靠 `tr()` 里的显式短路来保证**，不能靠字典里有 zh 项。
//
// 这里用**数据文件 + 合并**的方式补齐，而不是直接改 `i18n.dart` 的那个大 literal：
//   · 改动面小（i18n.dart 只加 3 行合并逻辑），不容易碰坏既有 5 种语言；
//   · 缺词仍有兜底 —— 查找链是 `locale → en → 中文原文`（见 i18n.dart 的 tr()），
//     **外加 zh 的显式短路**，所以即使将来新增中文 key 而这里没跟上，也只是回落英文，
//     不会再出现"半屏中文"；而中文用户永远是中文。
//
// 词条口径：key 一律是 `i18n.dart` 里出现过的中文原文，逐条对齐（不得自造 key，
// 自造的 key 永远不会被命中）。
